import { GROUP_MATCHES } from './league-schedule';

export function generateGroupMatches() {
  return GROUP_MATCHES.map(m => ({
    id: m.matchId,
    matchId: m.matchId,
    group: m.group,
    teamA: m.teamA,
    teamB: m.teamB,
    matchDay: m.matchDay,
    date: m.date,
    timeSpain: m.timeSpain,
    venue: m.venue,
    city: m.city,
    venueId: m.venueId,
    scoreA: null as number | null,
    scoreB: null as number | null,
  }));
}
